/*selectMasterCmClApCloseConfirmList*/
SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='SR01' AND FLAG ='Y' AND CODE = SITE) AS SITE, SUBSTR(TAX_BILL_NO,0,20) AS TAX_BILL_NO, TAX_BILL_NO AS RE_TAX_BILL_NO, BUYER_CODE AS BUYER_CODE, DECODE(SITE, 'SA', (SELECT BIZNPLC_CLSS_NM FROM KEPMDCP02@KEPCON WHERE BIZNPLC_CLSS_NO = BUYER_CODE), DECODE(SITE, 'KW', (SELECT BIZNPLC_CLSS_NM FROM KEPMDCP03@KEPCON WHERE BIZNPLC_CLSS_NO = BUYER_CODE), (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = BUYER_CODE))) AS BUYER_NAME, AGENT_CODE AS AGENT_CODE, DECODE(SITE, 'SA', (SELECT NVL(CP04.SPPLR_NM, CP01.ALANC_NM) FROM KEPMDCP04@KEPCON CP04, KEPMDCP01@KEPCON CP01 WHERE CP04.ALANC_ID = CP01.ALANC_ID AND CP04.SPPLR_ID = AGENT_CODE), -- 건설 DECODE(SITE, 'KW', (SELECT SUPPLIER_KOR FROM KEPMDCP05@KEPCON CP05 WHERE CP05.SPPLR_ID = AGENT_CODE), -- 유통 (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = AGENT_CODE))) AS AGENT_NAME, TAX_IRS_NO AS TAX_IRS_NO, AP_TYPE AS AP_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='APCL01' AND FLAG ='Y' AND CODE = AP_TYPE) AS AP_TYPE_TEXT, AP_CLOSE_MONTH AS AP_CLOSE_MONTH, ISSUE_DATE AS ISSUE_DATE, PM_LEGACY_USER_ID AS PM_LEGACY_USER_ID, PM_USER_NAME AS PM_USER_NAME, CONFIRM_USER_NAME AS CONFIRM_USER_NAME, KEP_DEPT AS KEP_DEPT, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE ='KRKORE0001' AND FLAG ='Y' AND CODE = KEP_DEPT) AS KEP_DEPT_NAME, LAST_MONTH_STOCK_AMT AS LAST_MONTH_STOCK_AMT, THIS_MONTH_SELL_AMT AS THIS_MONTH_SELL_AMT, THIS_MONTH_BUY_AMT AS THIS_MONTH_BUY_AMT, THIS_MONTH_STOCK_AMT AS THIS_MONTH_STOCK_AMT, CONFIRM_LEGACY_USER_ID AS CONFIRM_LEGACY_USER_ID, CONFIRM_USER_NAME AS CONFIRM_USER_NAME, TO_CHAR(ADD_DATE,'YY/MM/DD') AS ADD_DATE, ERP_SEND_YN AS ERP_SEND_YN, ERP_SEND_DATE AS ERP_SEND_DATE, NVL((SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE ='TX02' AND TEXT4 = 'AP' AND CODE = (SELECT TAX_TYPE FROM KEPTAPDT AP WHERE AP.TAX_BILL_NO = APLIST.TAX_BILL_NO AND AP.DEPT_CODE = APLIST.KEP_DEPT )),'과세매입') AS TAX_TYPE_TEXT FROM AP_CLOSE_CONFIRM_LIST APLIST WHERE 1=1 AND AP_CLOSE_MONTH = #{st_from_date}
AND KEP_DEPT = #{st_user_dept_cd}
AND AP_TYPE = #{st_ap_type}
AND AGENT_CODE = #{st_agent_code}
AND REPLACE(TAX_IRS_NO, '-','') LIKE '%' || REPLACE(#{st_irs_no},'-','') || '%'
AND CONFIRM_USER_NAME LIKE '%' || #{st_user_name} || '%'
AND ERP_SEND_YN = #{st_erp_send_yn}
AND APLIST.TAX_BILL_NO LIKE #{st_tax_bill_no} || '%'
ORDER BY SITE, KEP_DEPT, BUYER_CODE, AP_TYPE

mapper.update:
/*updateMasterCmClApCloseConfirm_cancle*/

	UPDATE 
    	BILL_CLOSE_USER_LIST
    	SET CLOSE_CMPL_YN = 'N'
		WHERE 1=1
		AND BILL_CLOSE_MONTH = #{AP_CLOSE_MONTH}
		AND LEGACY_USER_ID = #{CONFIRM_LEGACY_USER_ID}
		AND AGENT_CODE = #{AGENT_CODE}						
		AND CLOSE_TYPE = 'AP'
		AND CLOSE_CMPL_YN = 'Y'

/*updateMasterCmClApCloseConfirm_save*/

	UPDATE AP_CLOSE_CONFIRM_LIST
	SET 
	    LAST_MONTH_STOCK_AMT = #{LAST_MONTH_STOCK_AMT}
	  , THIS_MONTH_SELL_AMT = #{THIS_MONTH_SELL_AMT}
	  , THIS_MONTH_BUY_AMT = #{THIS_MONTH_BUY_AMT}
	  , THIS_MONTH_STOCK_AMT = #{THIS_MONTH_STOCK_AMT}
	WHERE 1=1
	AND AP_CLOSE_MONTH = #{AP_CLOSE_MONTH}			
	AND KEP_DEPT     = #{KEP_DEPT}		
	AND AP_TYPE = #{AP_TYPE}
	AND TAX_BILL_NO = #{RE_TAX_BILL_NO}

/*updateMasterCmClApCloseErpSendFlag_mro*/

	UPDATE KEPTAPDT
	SET 
	    CHANGE_USER_ID  = #{st_user_id}
	  , SEND_USER_ID   = #{st_user_id}
	  , CHANGE_DATE     = TO_CHAR(SYSDATE, 'YYYYMMDD')
	  , CHANGE_TIME     = TO_CHAR(SYSDATE, 'HH24MISS')
	  , SEND_DATE     = TO_CHAR(SYSDATE, 'YYYYMMDD')
	  , SEND_TIME     = TO_CHAR(SYSDATE, 'HH24MISS')
	  , IF_SEND_FLAG	= 'N'
	WHERE 1=1
	AND TAX_BILL_NO = #{TAX_BILL_NO}
	AND AP_CLOSE_MONTH = #{AP_CLOSE_MONTH}			
	AND SITE IN ('KA', 'KK')
	AND STATUS <> 'D'

/*updateMasterCmClApCloseConfirm_submit*/

	UPDATE
	BILL_CLOSE_USER_LIST
	SET
		CLOSE_CMPL_YN = 'N',
		CHANGE_DATE = SYSDATE
	WHERE 1=1
	AND LEGACY_USER_ID = #{CONFIRM_LEGACY_USER_ID}
	AND BILL_CLOSE_MONTH = #{AP_CLOSE_MONTH}
	AND CLOSE_TYPE = 'AP'
	AND AGENT_CODE = #{AGENT_CODE}

/*insertMasterCmClApCloseConfirm_stck_ap*/		 

	UPDATE AP_CLOSE_CONFIRM_LIST
	SET LAST_MONTH_STOCK_AMT =  LAST_MONTH_STOCK_AMT - (
															SELECT NVL(SUM(ROUND(AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))), 0) AS ITEM_AMT
															FROM ICOMGRDT GR
															WHERE GR.STATUS <> 'D'
															AND GR.AP_CLOSE_MONTH =  #{CLOSE_MONTH}
															AND GR.PROCESS_TYPE = '1'
															AND GR.AP_BILL_FLAG ='Y'
															AND (SELECT MAX(ORG_WAREHOUSE_CODE) FROM WMSSTCK WHERE STDCATLG_ID =
																							 (SELECT CMS_CATLG_ID FROM ICOMPODT
																								WHERE BUYER = GR.BUYER
																								AND PO_NO = GR.PO_NO
																								AND PO_SEQ = GR.PO_SEQ)
																 )  = #{WAREHOUSE_CODE}
														)
													  + (

													  	 	SELECT NVL(SUM(ROUND(AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))), 0) AS ITEM_AMT
															FROM ICOMGRDT GR
															WHERE GR.STATUS <> 'D'
															AND GR.AR_CLOSE_MONTH =  #{CLOSE_MONTH}
															AND GR.PROCESS_TYPE = '1'
															AND GR.AR_BILL_FLAG ='Y'
															AND (SELECT MAX(ORG_WAREHOUSE_CODE) FROM WMSSTCK WHERE STDCATLG_ID =
																							 (SELECT CMS_CATLG_ID FROM ICOMPODT
																								WHERE BUYER = GR.BUYER
																								AND PO_NO = GR.PO_NO
																								AND PO_SEQ = GR.PO_SEQ)
																 )  = #{WAREHOUSE_CODE}

													     )

	WHERE 1=1
	AND AP_TYPE ='ST'
	AND AP_CLOSE_MONTH = #{CLOSE_MONTH}
	AND KEP_DEPT = '005'
	AND BUYER_CODE = #{WAREHOUSE_CODE}

/*insertMasterCmClApCloseConfirm_stck_ap_v2*/		 

	UPDATE AP_CLOSE_CONFIRM_LIST
	SET LAST_MONTH_STOCK_AMT =  LAST_MONTH_STOCK_AMT - (
															SELECT NVL(SUM(ROUND(AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))), 0) AS ITEM_AMT
															FROM ICOMIVDT IV
															WHERE IV.STATUS <> 'D'
															AND IV.AP_CLOSE_MONTH =  #{CLOSE_MONTH}
															AND IV.PROCESS_TYPE = '1'
															AND IV.AP_BILL_FLAG ='Y'
															AND (SELECT MAX(ORG_WAREHOUSE_CODE) FROM WMSSTCK WHERE STDCATLG_ID =
																							 (SELECT CMS_CATLG_ID FROM ICOMPODT
																								WHERE BUYER = IV.BUYER
																								AND PO_NO = IV.PO_NO
																								AND PO_SEQ = IV.PO_SEQ)
																 )  = #{WAREHOUSE_CODE}
														)
													  + (

													  	 	SELECT NVL(SUM(ROUND(AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))), 0) AS ITEM_AMT
															FROM ICOMGRDT GR
															WHERE GR.STATUS <> 'D'
															AND GR.AR_CLOSE_MONTH =  #{CLOSE_MONTH}
															AND GR.PROCESS_TYPE = '1'
															AND GR.AR_BILL_FLAG ='Y'
															AND (SELECT MAX(ORG_WAREHOUSE_CODE) FROM WMSSTCK WHERE STDCATLG_ID =
																							 (SELECT CMS_CATLG_ID FROM ICOMPODT
																								WHERE BUYER = GR.BUYER
																								AND PO_NO = GR.PO_NO
																								AND PO_SEQ = GR.PO_SEQ)
																 )  = #{WAREHOUSE_CODE}

													     )

	WHERE 1=1
	AND AP_TYPE ='ST'
	AND AP_CLOSE_MONTH = #{CLOSE_MONTH}
	AND KEP_DEPT = '005'
	AND BUYER_CODE = #{WAREHOUSE_CODE}
